package org.lastphone.app.nativebridge

import android.util.Base64
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test
import org.junit.runner.RunWith
import java.io.ByteArrayInputStream
import java.io.File
import java.util.zip.GZIPInputStream
import kotlin.math.sqrt

@RunWith(AndroidJUnit4::class)
class NativeEmbeddingsTest {
    @Test fun actualOnnxInferenceUsesAllInputsAndNormalizesClsOnly() {
        // Generated by src/androidTest/fixtures/make_cls_fixture.py (onnx 1.17.0).
        val fixture = ""
        val context = InstrumentationRegistry.getInstrumentation().targetContext
        val model = File(context.cacheDir, "test-cls.onnx")
        try {
            GZIPInputStream(ByteArrayInputStream(Base64.decode(fixture, Base64.DEFAULT))).use { input ->
                model.outputStream().use { input.copyTo(it) }
            }
            NativeEmbeddings().use { runtime ->
                val info = JSONObject(runtime.load(model.path, 2))
                val names: JSONArray = info.getJSONArray("inputs")
                assertEquals(3, names.length())
                val vectors = runtime.embed(
                    arrayOf(longArrayOf(1, 77, 88), longArrayOf(2, 99, 100)),
                    arrayOf(longArrayOf(1, 1, 1), longArrayOf(1, 1, 1)),
                    arrayOf(longArrayOf(2, 9, 8), longArrayOf(0, 7, 6)),
                )
                assertEquals(2, vectors.size)
                for ((row, offset) in listOf(6f, 3f).withIndex()) {
                    val norm = sqrt((offset + 3) * (offset + 3) + (offset + 4) * (offset + 4) + 382 * offset * offset)
                    assertEquals(384, vectors[row].size)
                    assertEquals((offset + 3) / norm, vectors[row][0], 1e-6f)
                    assertEquals((offset + 4) / norm, vectors[row][1], 1e-6f)
                    assertEquals(offset / norm, vectors[row][383], 1e-6f)
                    assertEquals(1f, vectors[row].sumOf { (it * it).toDouble() }.toFloat(), 1e-5f)
                }
                runtime.close()
                try {
                    runtime.embed(arrayOf(longArrayOf(1)), arrayOf(longArrayOf(1)), null)
                    fail("Inference accepted a closed session.")
                } catch (_: IllegalStateException) { }
            }
        } finally { model.delete() }
    }
}
